# b1u7 — Culture and traditions: practice sentences, 12 per lesson.
DRILLS = {
 "b1u7l1": [
  ("In Thailand, Songkran is celebrated every year on April 13.", "ที่ประเทศไทย มีการฉลองสงกรานต์ทุกปีในวันที่สิบสามเมษายน", "thîi prà-thêet-thai, mii kaan chà-lɔ̌ɔng sǒng-kraan thúk pii nai wan thîi sìp-sǎam mee-sǎa-yon"),
  ("We came to wish you all a happy holiday.", "เรามาอวยพรให้พวกคุณมีความสุขในวันหยุดนี้", "rao maa uai-phɔɔn hâi phûak-khun mii khwaam-sùk nai wan-yùt níi"),
  ("I brought this gift for you from Italy.", "ฉันเอาของขวัญชิ้นนี้มาจากอิตาลีให้คุณ", "chǎn ao khɔ̌ɔng-khwǎn chín níi maa jàak ì-taa-lîi hâi khun"),
  ("The guests invited to the banquet started arriving toward evening.", "แขกที่ได้รับเชิญมางานเลี้ยงเริ่มมาถึงตอนใกล้ค่ำ", "khɛ̀ɛk thîi dâi-ráp chəən maa ngaan-líang rə̂əm maa thʉ̌ng tɔɔn klâi khâm"),
  ("This beautiful custom was handed down to us by our ancestors.", "ประเพณีที่งดงามนี้สืบทอดมาจากบรรพบุรุษของเรา", "prà-phee-nii thîi ngót-ngaam níi sʉ̀ʉp-thɔ̂ɔt maa jàak ban-phá-bù-rùt khɔ̌ɔng rao"),
  ("What traditions does your family have on Songkran day? (plural)", "ในวันสงกรานต์ ครอบครัวของพวกคุณมีประเพณีอะไรบ้าง", "nai wan sǒng-kraan, khrɔ̂ɔp-khrua khɔ̌ɔng phûak-khun mii prà-phee-nii à-rai bâang?"),
  ("For me, my friends' good wishes are the best gift.", "สำหรับฉัน คำอวยพรจากเพื่อนๆ คือของขวัญที่ดีที่สุด", "sǎm-ràp chǎn, kham-uai-phɔɔn jàak phʉ̂an-phʉ̂an khʉʉ khɔ̌ɔng-khwǎn thîi dii thîi-sùt"),
  ("If you have time, come to tomorrow's banquet!", "ถ้ามีเวลา มางานเลี้ยงพรุ่งนี้นะ", "thâa mii wee-laa, maa ngaan-líang phrûng-níi ná!"),
  ("In our culture, it's customary to take gifts to relatives on holidays.", "ในวัฒนธรรมของเรา ช่วงเทศกาลมักจะเอาของฝากไปให้ญาติ", "nai wát-thá-ná-tham khɔ̌ɔng rao, chûang thêet-sà-kaan mák jà ao khɔ̌ɔng-fàak pai hâi yâat"),
  ("This year we didn't celebrate New Year's because my grandmother was sick.", "ปีนี้เราไม่ได้ฉลองปีใหม่เพราะคุณยายป่วย", "pii níi rao mâi dâai chà-lɔ̌ɔng pii-mài phrɔ́ khun-yaai pùai"),
  ("Young people shouldn't forget the old customs.", "คนรุ่นใหม่ไม่ควรลืมประเพณีเก่าๆ", "khon rûn mài mâi khuan lʉʉm prà-phee-nii kào-kào"),
  ("How beautiful this year's Songkran celebration was!", "งานสงกรานต์ปีนี้สวยงามมากเลย", "ngaan sǒng-kraan pii níi sǔai-ngaam mâak ləəi!"),
 ],
 "b1u7l2": [
  ("Thais are famous all over the world for their hospitality.", "คนไทยมีชื่อเสียงไปทั่วโลกเรื่องความมีน้ำใจต่อแขก", "khon-thai mii chʉ̂ʉ-sǐang pai thûa lôok rʉ̂ang khwaam-mii-nám-jai tɔ̀ɔ khɛ̀ɛk"),
  ("The host served the guests tea first, then pad thai.", "เจ้าภาพเสิร์ฟชาให้แขกก่อน แล้วค่อยเสิร์ฟผัดไทย", "jâo-phâap sə̀əp chaa hâi khɛ̀ɛk kɔ̀ɔn, lɛ́ɛo khɔ̂i sə̀əp phàt-thai"),
  ("I've never tasted this dish; what is it made of?", "ฉันไม่เคยชิมอาหารจานนี้เลย ทำจากอะไรเหรอ", "chǎn mâi khəəi chim aa-hǎan jaan níi ləəi, tham jàak à-rai rə̌ə?"),
  ("Could you please write down the recipe for this salad for me? (formal)", "รบกวนช่วยเขียนสูตรยำนี้ให้หน่อยได้ไหมคะ", "róp-kuan chûai khǐan sùut yam níi hâi nɔ̀i dâai mǎi khá?"),
  ("I brought all the ingredients for pad thai from the market.", "ฉันเอาวัตถุดิบทำผัดไทยทั้งหมดมาจากตลาด", "chǎn ao wát-thù-dìp tham phàt-thai tháng-mòt maa jàak tà-làat"),
  ("We need to set the table before the guests arrive.", "เราต้องจัดโต๊ะก่อนแขกมาถึง", "rao tɔ̂ng jàt tó kɔ̀ɔn khɛ̀ɛk maa thʉ̌ng"),
  ("The host stood up and made a toast.", "เจ้าภาพลุกขึ้นยืนกล่าวดื่มอวยพร", "jâo-phâap lúk khʉ̂n yʉʉn klàao dʉ̀ʉm-uai-phɔɔn"),
  ("The table was so full that we couldn't eat everything.", "อาหารบนโต๊ะเยอะมากจนเรากินไม่หมด", "aa-hǎan bon tó yə́ mâak jon rao kin mâi mòt"),
  ("Would you like to try this dish too? (formal)", "คุณจะลองชิมอาหารจานนี้ด้วยไหมคะ", "khun jà lɔɔng chim aa-hǎan jaan níi dûai mǎi khá?"),
  ("In Italy, what dishes are usually served to guests?", "ที่อิตาลี ปกติเขาเสิร์ฟอาหารอะไรให้แขก", "thîi ì-taa-lîi, pòk-kà-tì khǎo sə̀əp aa-hǎan à-rai hâi khɛ̀ɛk?"),
  ("What ingredients do you need for this recipe?", "สูตรนี้ต้องใช้วัตถุดิบอะไรบ้าง", "sùut níi tɔ̂ng chái wát-thù-dìp à-rai bâang?"),
  ("I don't know who will make the toast today.", "ฉันไม่รู้ว่าวันนี้ใครจะเป็นคนกล่าวอวยพร", "chǎn mâi rúu wâa wan-níi khrai jà pen khon klàao uai-phɔɔn"),
 ],
 "b1u7l3": [
  ("The craftsmen of Chiang Mai make the most beautiful ceramics.", "ช่างฝีมือที่เชียงใหม่ทำเครื่องปั้นดินเผาที่สวยที่สุด", "châang-fǐi-mʉʉ thîi chiang-mài tham khrʉ̂ang-pân-din-phǎo thîi sǔai thîi-sùt"),
  ("I want to give my mother a silk scarf for her birthday.", "ฉันอยากให้ผ้าพันคอไหมเป็นของขวัญวันเกิดแม่", "chǎn yàak hâi phâa-phan-khɔɔ mǎi pen khɔ̌ɔng-khwǎn wan-kə̀ət mɛ̂ɛ"),
  ("This silk cloth was my grandmother's and it's more than a hundred years old.", "ผ้าไหมผืนนี้เป็นของคุณยาย อายุกว่าร้อยปีแล้ว", "phâa-mǎi phʉ̌ʉn níi pen khɔ̌ɔng khun-yaai, aa-yú kwàa rɔ́ɔi pii lɛ́ɛo"),
  ("My mother worked on this embroidery for three months.", "แม่ใช้เวลาปักผ้าชิ้นนี้สามเดือน", "mɛ̂ɛ chái wee-laa pàk phâa chín níi sǎam dʉan"),
  ("I'd like to know more about the art of mural painting.", "ฉันอยากรู้เรื่องศิลปะจิตรกรรมฝาผนังมากขึ้น", "chǎn yàak rúu rʉ̂ang sǐn-lá-pà jìt-trà-kam-fǎa-phà-nǎng mâak khʉ̂n"),
  ("People come from all over the world to see the architecture of Ayutthaya.", "ผู้คนมาจากทั่วโลกเพื่อชมสถาปัตยกรรมของอยุธยา", "phûu-khon maa jàak thûa lôok phʉ̂a chom sà-thǎa-pàt-tà-yá-kam khɔ̌ɔng à-yút-thá-yaa"),
  ("After the restoration, this temple became much more beautiful.", "หลังบูรณะ วัดนี้สวยขึ้นมาก", "lǎng buu-rá-ná, wát níi sǔai khʉ̂n mâak"),
  ("We must preserve this heritage for our children.", "เราต้องอนุรักษ์มรดกนี้ไว้ให้ลูกหลาน", "rao tɔ̂ng à-nú-rák mɔɔ-rá-dòk níi wái hâi lûuk-lǎan"),
  ("Do you know how long the silk exhibition will be open? (formal)", "ทราบไหมคะว่านิทรรศการผ้าไหมจะเปิดถึงเมื่อไร", "sâap mǎi khá wâa ní-tháat-sà-kaan phâa-mǎi jà pə̀ət thʉ̌ng mʉ̂a-rai?"),
  ("I still remember the murals I saw at the exhibition.", "ฉันยังจำภาพจิตรกรรมที่เห็นในนิทรรศการได้", "chǎn yang jam phâap jìt-trà-kam thîi hěn nai ní-tháat-sà-kaan dâai"),
  ("Why is this silk cloth so expensive?", "ทำไมผ้าไหมผืนนี้แพงจัง", "tham-mai phâa-mǎi phʉ̌ʉn níi phɛɛng jang?"),
  ("My grandfather says a true craftsman is never in a hurry.", "ปู่บอกว่าช่างฝีมือที่แท้จริงไม่เคยรีบร้อน", "pùu bɔ̀ɔk wâa châang-fǐi-mʉʉ thîi thɛ́ɛ-jing mâi khəəi rîip-rɔ́ɔn"),
 ],
 "b1u7l4": [
  ("Italians make a lot of gestures when they talk.", "คนอิตาลีใช้ท่าทางเยอะเวลาพูด", "khon ì-taa-lîi chái thâa-thaang yə́ wee-laa phûut"),
  ("Be careful: here this gesture is considered rude. (formal)", "ระวังนะคะ ที่นี่ท่าทางนี้ถือว่าไม่สุภาพ", "rá-wang ná khá, thîi-nîi thâa-thaang níi thʉ̌ʉ wâa mâi sù-phâap"),
  ("At work, punctuality is important everywhere.", "ในที่ทำงาน การตรงต่อเวลาสำคัญทุกที่", "nai thîi-tham-ngaan, kaan trong-tɔ̀ɔ-wee-laa sǎm-khan thúk thîi"),
  ("I adapted to my new life very quickly.", "ฉันปรับตัวเข้ากับชีวิตใหม่ได้เร็วมาก", "chǎn pràp-tua khâo kàp chii-wít mài dâai reo mâak"),
  ("Was it hard for you to adapt to life here? (formal)", "คุณปรับตัวกับชีวิตที่นี่ยากไหมครับ", "khun pràp-tua kàp chii-wít thîi-nîi yâak mǎi khráp?"),
  ("In Thailand, touching someone's head is taboo.", "ที่ประเทศไทย การจับหัวคนอื่นเป็นเรื่องต้องห้าม", "thîi prà-thêet-thai, kaan jàp hǔa khon ʉ̀ʉn pen rʉ̂ang tɔ̂ng-hâam"),
  ("It was just a small cultural misunderstanding.", "มันเป็นแค่ความเข้าใจผิดทางวัฒนธรรมเล็กๆ", "man pen khɛ̂ɛ khwaam-khâo-jai-phìt thaang wát-thá-ná-tham lék-lék"),
  ("It surprised me that in Italy they eat dinner very late.", "ฉันแปลกใจที่คนอิตาลีกินข้าวเย็นดึกมาก", "chǎn plɛ̀ɛk-jai thîi khon ì-taa-lîi kin khâao-yen dʉ̀k mâak"),
  ("What is normal in Italy may seem strange here.", "สิ่งที่เป็นเรื่องปกติในอิตาลี อาจดูแปลกที่นี่", "sìng thîi pen rʉ̂ang pòk-kà-tì nai ì-taa-lîi, àat duu plɛ̀ɛk thîi-nîi"),
  ("If you don't know the rules of etiquette, a cultural misunderstanding can happen. (formal)", "ถ้าคุณไม่รู้มารยาท ก็อาจเกิดความเข้าใจผิดทางวัฒนธรรมได้ค่ะ", "thâa khun mâi rúu maa-rá-yâat, kɔ̂ɔ àat kə̀ət khwaam-khâo-jai-phìt thaang wát-thá-ná-tham dâai khâ"),
  ("Which cultural habit surprised you the most?", "นิสัยทางวัฒนธรรมแบบไหนที่ทำให้คุณแปลกใจที่สุด", "ní-sǎi thaang wát-thá-ná-tham bɛ̀ɛp nǎi thîi tham-hâi khun plɛ̀ɛk-jai thîi-sùt?"),
  ("I think looking at your phone while eating is rude.", "ฉันว่าการดูโทรศัพท์ระหว่างกินข้าวเป็นการเสียมารยาท", "chǎn wâa kaan duu thoo-rá-sàp rá-wàang kin khâao pen kaan sǐa-maa-rá-yâat"),
 ],
 "b1u7x1": [
  ("The wedding ceremony started in the morning and went on until evening.", "พิธีแต่งงานเริ่มตั้งแต่เช้าและดำเนินไปจนถึงเย็น", "phí-thii tɛ̀ng-ngaan rə̂əm tâng-tɛ̀ɛ cháao lɛ́ dam-nəən pai jon thʉ̌ng yen"),
  ("Songkran is the biggest national holiday in Thailand.", "สงกรานต์เป็นวันหยุดเทศกาลที่ใหญ่ที่สุดในประเทศไทย", "sǒng-kraan pen wan-yùt thêet-sà-kaan thîi yài thîi-sùt nai prà-thêet-thai"),
  ("Easter is one of the most important religious holidays in Italy.", "อีสเตอร์เป็นหนึ่งในวันสำคัญทางศาสนาที่ยิ่งใหญ่ที่สุดของอิตาลี", "ii-sà-tə̂ə pen nʉ̀ng nai wan-sǎm-khan thaang sàat-sà-nǎa thîi yîng-yài thîi-sùt khɔ̌ɔng ì-taa-lîi"),
  ("My grandfather blessed the bride and groom and wished them happiness.", "ปู่ให้พรเจ้าบ่าวเจ้าสาวและอวยพรให้มีความสุข", "pùu hâi phɔɔn jâo-bàao-jâo-sǎao lɛ́ uai-phɔɔn hâi mii khwaam-sùk"),
  ("The girls in national costume performed the ritual dance.", "สาวๆ ในชุดประจำชาติร่ายรำตามพิธี", "sǎao-sǎao nai chút prà-jam châat râai-ram taam phí-thii"),
  ("The elderly still know the traditional songs by heart.", "ผู้สูงอายุยังจำเพลงพื้นบ้านได้ขึ้นใจ", "phûu-sǔung-aa-yú yang jam phleeng-phʉ́ʉn-bâan dâai khʉ̂n-jai"),
  ("The host of the wedding invited all the guests to a big banquet.", "เจ้าภาพงานแต่งเชิญแขกทุกคนมางานเลี้ยงใหญ่", "jâo-phâap ngaan-tɛ̀ng chəən khɛ̀ɛk thúk khon maa ngaan-líang yài"),
  ("On New Year's Eve we watched the fireworks with the whole family.", "คืนวันสิ้นปี เราดูพลุกันทั้งครอบครัว", "khʉʉn wan-sîn-pii, rao duu phlú kan tháng khrɔ̂ɔp-khrua"),
  ("Before the holiday, we made decorations together with the children.", "ก่อนวันหยุดเทศกาล เราทำของตกแต่งกับเด็กๆ", "kɔ̀ɔn wan-yùt thêet-sà-kaan, rao tham khɔ̌ɔng-tòk-tɛ̀ng kàp dèk-dèk"),
  ("This folk tradition has been kept alive for a thousand years.", "ประเพณีพื้นบ้านนี้สืบทอดกันมาเป็นพันปี", "prà-phee-nii phʉ́ʉn-bâan níi sʉ̀ʉp-thɔ̂ɔt kan maa pen phan pii"),
  ("According to custom, on a holiday you should first give your good wishes to the elders.", "ตามประเพณี ในวันเทศกาลต้องไปอวยพรผู้ใหญ่ก่อน", "taam prà-phee-nii, nai wan thêet-sà-kaan tɔ̂ng pai uai-phɔɔn phûu-yài kɔ̀ɔn"),
  ("Do you know what time tomorrow's ceremony starts? (formal)", "ทราบไหมครับว่าพิธีพรุ่งนี้เริ่มกี่โมง", "sâap mǎi khráp wâa phí-thii phrûng-níi rə̂əm kìi moong?"),
 ],
 "b1u7x2": [
  ("Pad thai is Thailand's most famous national dish.", "ผัดไทยเป็นอาหารประจำชาติที่มีชื่อเสียงที่สุดของไทย", "phàt-thai pen aa-hǎan prà-jam châat thîi mii chʉ̂ʉ-sǐang thîi-sùt khɔ̌ɔng thai"),
  ("The cook doesn't tell anyone his secret ingredient.", "พ่อครัวไม่บอกใครเรื่องส่วนผสมลับของเขา", "phɔ̂ɔ-khrua mâi bɔ̀ɔk khrai rʉ̂ang sùan-phà-sǒm láp khɔ̌ɔng khǎo"),
  ("For spring rolls, you have to roll the wrappers out very thin.", "ทำปอเปี๊ยะต้องรีดแป้งให้บางมาก", "tham pɔɔ-pía tɔ̂ng rîit pɛ̂ɛng hâi baang mâak"),
  ("On rainy days there's nothing better than a hot tom yum.", "วันฝนตก ไม่มีอะไรดีไปกว่าต้มยำร้อนๆ", "wan fǒn tòk, mâi mii à-rai dii pai kwàa tôm-yam rɔ́ɔn-rɔ́ɔn"),
  ("We marinated the meat in the evening and cooked it in the morning.", "เราหมักเนื้อไว้ตอนเย็น แล้วเอามาทำตอนเช้า", "rao màk nʉ́a wái tɔɔn yen, lɛ́ɛo ao maa tham tɔɔn cháao"),
  ("Don't put too many chilies in the soup; the children won't eat it. (formal)", "อย่าใส่พริกในซุปเยอะเกินไปนะคะ เด็กๆ จะกินไม่ได้", "yàa sài phrík nai súp yə́ kəən pai ná khá, dèk-dèk jà kin mâi dâai"),
  ("Serve the pad thai hot; if it gets cold, it loses its flavor. (plural)", "พวกคุณเสิร์ฟผัดไทยตอนร้อนๆ นะ ถ้าเย็นแล้วจะไม่อร่อย", "phûak-khun sə̀əp phàt-thai tɔɔn rɔ́ɔn-rɔ́ɔn ná, thâa yen lɛ́ɛo jà mâi à-rɔ̀i"),
  ("Every week my grandmother pounds homemade curry paste in the mortar.", "ทุกสัปดาห์ยายตำพริกแกงเองในครก", "thúk sàp-daa yaai tam phrík-kɛɛng eeng nai khrók"),
  ("Which Thai sweet goes well with green tea?", "ขนมไทยอะไรเข้ากับชาเขียว", "khà-nǒm-thai à-rai khâo kàp chaa-khǐao?"),
  ("The guests were very happy to see the decorated table.", "แขกดีใจมากที่เห็นโต๊ะที่จัดไว้สวยงาม", "khɛ̀ɛk dii-jai mâak thîi hěn tó thîi jàt wái sǔai-ngaam"),
  ("It's a recipe passed down through generations; we don't give it to anyone.", "เป็นสูตรที่สืบทอดกันมาหลายรุ่น เราไม่บอกใคร", "pen sùut thîi sʉ̀ʉp-thɔ̂ɔt kan maa lǎai rûn, rao mâi bɔ̀ɔk khrai"),
  ("This mango sticky rice reminds me of the taste of childhood.", "ข้าวเหนียวมะม่วงนี้ทำให้ฉันนึกถึงรสชาติตอนเด็ก", "khâao-nǐao-má-mûang níi tham-hâi chǎn nʉ́k thʉ̌ng rót-châat tɔɔn dèk"),
 ],
 "b1u7x3": [
  ("We got the house ready to welcome our honored guests.", "เราเตรียมบ้านไว้ต้อนรับแขกผู้มีเกียรติ", "rao triam bâan wái tɔ̂ɔn-ráp khɛ̀ɛk phûu-mii-kìat"),
  ("The host immediately seated us in the place of honor.", "เจ้าภาพเชิญเรานั่งที่นั่งของแขกเกียรติยศทันที", "jâo-phâap chəən rao nâng thîi-nâng khɔ̌ɔng khɛ̀ɛk kìat-tì-yót than-thii"),
  ("In our culture, as soon as a guest arrives, they are offered water.", "ในวัฒนธรรมของเรา พอแขกมาถึงก็จะยกน้ำมาให้ทันที", "nai wát-thá-ná-tham khɔ̌ɔng rao, phɔɔ khɛ̀ɛk maa thʉ̌ng kɔ̂ɔ jà yók náam maa hâi than-thii"),
  ("In Italy, guests usually don't take off their shoes.", "ที่อิตาลี ปกติแขกจะไม่ถอดรองเท้า", "thîi ì-taa-lîi, pòk-kà-tì khɛ̀ɛk jà mâi thɔ̀ɔt rɔɔng-tháao"),
  ("I ate a little more pad thai because the host insisted.", "ฉันกินผัดไทยเพิ่มอีกนิดเพราะเจ้าภาพคะยั้นคะยอ", "chǎn kin phàt-thai phə̂əm ìik nít phrɔ́ jâo-phâap khá-yán-khá-yɔɔ"),
  ("If you're full, you can politely refuse. (formal)", "ถ้าอิ่มแล้ว ปฏิเสธอย่างสุภาพได้ค่ะ", "thâa ìm lɛ́ɛo, pà-tì-sèet yàang sù-phâap dâai khâ"),
  ("After dinner, it's good manners to praise the cook.", "หลังกินข้าวเย็น การชมคนทำอาหารถือเป็นมารยาทที่ดี", "lǎng kin khâao-yen, kaan chom khon tham aa-hǎan thʉ̌ʉ pen maa-rá-yâat thîi dii"),
  ("At the table, the host served rice to everyone.", "ที่โต๊ะอาหาร เจ้าภาพตักข้าวให้ทุกคน", "thîi tó aa-hǎan, jâo-phâap tàk khâao hâi thúk khon"),
  ("In our culture, it's customary to walk guests out to the street.", "ในวัฒนธรรมของเรา มักจะเดินไปส่งแขกถึงถนน", "nai wát-thá-ná-tham khɔ̌ɔng rao, mák jà dəən pai sòng khɛ̀ɛk thʉ̌ng thà-nǒn"),
  ("Thank you so much for the dinner invitation! (formal)", "ขอบคุณมากครับที่เชิญมาทานข้าวเย็น", "khɔ̀ɔp-khun mâak khráp thîi chəən maa thaan khâao-yen!"),
  ("Sorry for our unexpected visit; we were nearby.", "ขอโทษที่มาโดยไม่บอกล่วงหน้า พอดีเราอยู่แถวนี้", "khɔ̌ɔ-thôot thîi maa dooi mâi bɔ̀ɔk lûang-nâa, phɔɔ-dii rao yùu thɛ̌ɛo-níi"),
  ("I want to go to their place with a gift; what should I get?", "ฉันอยากเอาของขวัญไปบ้านเขา ควรซื้ออะไรดี", "chǎn yàak ao khɔ̌ɔng-khwǎn pai bâan khǎo, khuan sʉ́ʉ à-rai dii?"),
 ],
 "b1u7x4": [
  ("The master craftsman has worked in his workshop for thirty years.", "ครูช่างทำงานอยู่ในโรงช่างของเขามาสามสิบปีแล้ว", "khruu-châang tham-ngaan yùu nai roong-châang khɔ̌ɔng khǎo maa sǎam-sìp pii lɛ́ɛo"),
  ("The master wants to pass his craft on to future generations through his apprentices.", "ครูช่างอยากถ่ายทอดฝีมือให้คนรุ่นหลังผ่านลูกศิษย์", "khruu-châang yàak thàai-thɔ̂ɔt fǐi-mʉʉ hâi khon rûn lǎng phàan lûuk-sìt"),
  ("This silk was woven by hand on a wooden loom.", "ผ้าไหมผืนนี้ทอด้วยมือบนกี่ไม้", "phâa-mǎi phʉ̌ʉn níi thɔɔ dûai mʉʉ bon kìi máai"),
  ("During summer vacation, my daughter learned to embroider from her grandmother.", "ช่วงปิดเทอมหน้าร้อน ลูกสาวฉันหัดปักผ้ากับคุณยาย", "chûang pìt-thəəm nâa-rɔ́ɔn, lûuk-sǎao chǎn hàt pàk phâa kàp khun-yaai"),
  ("When he was young, my grandfather carved wood and made beautiful doors.", "ตอนหนุ่มๆ ปู่แกะสลักไม้และทำประตูสวยๆ", "tɔɔn nùm-nùm, pùu kɛ̀-sà-làk máai lɛ́ tham prà-tuu sǔai-sǔai"),
  ("In the workshop, the children made small clay pots.", "ที่โรงช่าง เด็กๆ ปั้นหม้อดินใบเล็กๆ", "thîi roong-châang, dèk-dèk pân mɔ̂ɔ-din bai lék-lék"),
  ("They glaze the pots and then fire them in the kiln.", "เขาเคลือบหม้อแล้วเอาไปเผาในเตา", "khǎo khlʉ̂ap mɔ̂ɔ lɛ́ɛo ao pai phǎo nai tao"),
  ("Symmetry is very important in Thai patterns.", "ความสมมาตรสำคัญมากในลายไทย", "khwaam-sǒm-mâat sǎm-khan mâak nai laai-thai"),
  ("Handmade items are more expensive, but of better quality.", "ของทำมือแพงกว่า แต่คุณภาพดีกว่า", "khɔ̌ɔng tham-mʉʉ phɛɛng kwàa, tɛ̀ɛ khun-ná-phâap dii kwàa"),
  ("This pot is one of a kind; there isn't another.", "หม้อใบนี้มีใบเดียวในโลก ไม่มีใบอื่นเหมือน", "mɔ̂ɔ bai níi mii bai diao nai lôok, mâi mii bai ʉ̀ʉn mʉ̌an"),
  ("Now it has become much harder to find good raw materials.", "ตอนนี้หาวัตถุดิบดีๆ ยากขึ้นมาก", "tɔɔn-níi hǎa wát-thù-dìp dii-dii yâak khʉ̂n mâak"),
  ("At the crafts market I found beautiful gifts at a fair price.", "ที่ตลาดงานฝีมือ ฉันเจอของขวัญสวยๆ ในราคาที่เหมาะสม", "thîi tà-làat ngaan-fǐi-mʉʉ, chǎn jəə khɔ̌ɔng-khwǎn sǔai-sǔai nai raa-khaa thîi mɔ̀-sǒm"),
 ],
 "b1u7x5": [
  ("The khim is one of the most famous traditional Thai instruments.", "ขิมเป็นเครื่องดนตรีไทยที่มีชื่อเสียงที่สุดชนิดหนึ่ง", "khǐm pen khrʉ̂ang-don-trii-thai thîi mii chʉ̂ʉ-sǐang thîi-sùt chá-nít nʉ̀ng"),
  ("The melody of this song is very nice, but I didn't understand the lyrics.", "ทำนองเพลงนี้เพราะมาก แต่ฉันไม่เข้าใจเนื้อเพลง", "tham-nɔɔng phleeng níi phrɔ́ mâak, tɛ̀ɛ chǎn mâi khâo-jai nʉ́a-phleeng"),
  ("The rhythm of this dance is too fast for me.", "จังหวะของการเต้นนี้เร็วเกินไปสำหรับฉัน", "jang-wà khɔ̌ɔng kaan tên níi reo kəən pai sǎm-ràp chǎn"),
  ("The singer's voice filled the whole hall.", "เสียงของนักร้องดังก้องไปทั้งห้องโถง", "sǐang khɔ̌ɔng nák-rɔ́ɔng dang-kɔ̂ng pai tháng hɔ̂ng-thǒong"),
  ("At the festival, the choir and the orchestra performed together.", "ในงานเทศกาล คณะนักร้องประสานเสียงกับวงออร์เคสตราแสดงร่วมกัน", "nai ngaan thêet-sà-kaan, khá-ná nák-rɔ́ɔng prà-sǎan-sǐang kàp wong ɔɔ-khés-traa sà-dɛɛng rûam kan"),
  ("Before going on the big stage, we rehearsed a lot.", "ก่อนขึ้นเวทีใหญ่ เราซ้อมกันเยอะมาก", "kɔ̀ɔn khʉ̂n wee-thii yài, rao sɔ́ɔm kan yə́ mâak"),
  ("At the wedding everyone did the folk dance, even my grandmother.", "ในงานแต่ง ทุกคนรำวงกัน แม้แต่คุณยาย", "nai ngaan-tɛ̀ng, thúk khon ram-wong kan, mɛ́ɛ-tɛ̀ɛ khun-yaai"),
  ("Can you teach me these dance steps? (formal)", "ช่วยสอนท่าเต้นนี้ให้หน่อยได้ไหมคะ", "chûai sɔ̌ɔn thâa-tên níi hâi nɔ̀i dâai mǎi khá?"),
  ("When the traditional concert ended, everyone applauded for a long time.", "พอคอนเสิร์ตดนตรีไทยจบ ทุกคนปรบมือกันอยู่นาน", "phɔɔ khɔn-sə̀ət don-trii-thai jòp, thúk khon pròp-mʉʉ kan yùu naan"),
  ("The cheering audience called the singer back for an encore.", "ผู้ชมโห่ร้องเรียกนักร้องกลับมาร้องอีกเพลง", "phûu-chom hòo-rɔ́ɔng rîak nák-rɔ́ɔng klàp maa rɔ́ɔng ìik phleeng"),
  ("When does your favorite band's new album come out?", "อัลบั้มใหม่ของวงที่คุณชอบจะออกเมื่อไร", "an-bâm mài khɔ̌ɔng wong thîi khun chɔ̂ɔp jà ɔ̀ɔk mʉ̂a-rai?"),
  ("If young people don't learn them, these songs will be forgotten.", "ถ้าคนรุ่นใหม่ไม่เรียน เพลงเหล่านี้ก็จะถูกลืม", "thâa khon rûn mài mâi rian, phleeng lào-níi kɔ̂ɔ jà thùuk lʉʉm"),
 ],
 "b1u7x6": [
  ("I read the proverb several times to understand its meaning.", "ฉันอ่านสุภาษิตนี้หลายรอบเพื่อให้เข้าใจความหมาย", "chǎn àan sù-phaa-sìt níi lǎai rɔ̂ɔp phʉ̂a hâi khâo-jai khwaam-mǎai"),
  ("It's very hard to translate this expression into another language.", "สำนวนนี้แปลเป็นภาษาอื่นยากมาก", "sǎm-nuan níi plɛɛ pen phaa-sǎa ʉ̀ʉn yâak mâak"),
  ("My grandmother's words are full of folk wisdom.", "คำพูดของคุณยายเต็มไปด้วยภูมิปัญญาชาวบ้าน", "kham-phûut khɔ̌ɔng khun-yaai tem pai dûai phuu-mí-pan-yaa-chaao-bâan"),
  ("Do you believe in fate, or does everything depend on us? (formal)", "คุณเชื่อเรื่องโชคชะตาไหมคะ หรือทุกอย่างขึ้นอยู่กับตัวเรา", "khun chʉ̂a rʉ̂ang chôok-chá-taa mǎi khá, rʉ̌ʉ thúk yàang khʉ̂n-yùu-kàp tua rao?"),
  ("To protect against bad luck, they tied a sacred thread on the child's wrist.", "เพื่อป้องกันเคราะห์ร้าย เขาผูกสายสิญจน์ที่ข้อมือเด็ก", "phʉ̂a pɔ̂ng-kan khrɔ́-ráai, khǎo phùuk sǎai-sǐn thîi khɔ̂ɔ-mʉʉ dèk"),
  ("Italians also do superstitious things before a soccer game.", "คนอิตาลีก็ทำเรื่องโชคลางก่อนแข่งฟุตบอลเหมือนกัน", "khon ì-taa-lîi kɔ̂ɔ tham rʉ̂ang chôok-laang kɔ̀ɔn khɛ̀ng fút-bɔn mʉ̌an-kan"),
  ("My grandmother always interprets our dreams for us.", "คุณยายทำนายฝันให้พวกเราเสมอ", "khun-yaai tham-naai fǎn hâi phûak-rao sà-mə̌ə"),
  ("They say everyone has their own lot in life.", "เขาว่ากันว่าทุกคนมีชะตาชีวิตของตัวเอง", "khǎo wâa kan wâa thúk khon mii chá-taa-chii-wít khɔ̌ɔng tua-eeng"),
  ("Respect for the elderly is one of our most important values.", "การเคารพผู้ใหญ่เป็นค่านิยมที่สำคัญที่สุดอย่างหนึ่งของเรา", "kaan khao-róp phûu-yài pen khâa-ní-yom thîi sǎm-khan thîi-sùt yàang nʉ̀ng khɔ̌ɔng rao"),
  ("When I was a child, my grandfather used to tell me folk tales.", "ตอนเด็กๆ ปู่ชอบเล่านิทานพื้นบ้านให้ฉันฟัง", "tɔɔn dèk-dèk, pùu chɔ̂ɔp lâo ní-thaan-phʉ́ʉn-bâan hâi chǎn fang"),
  ("Everyone knows the hero of this legend.", "ทุกคนรู้จักวีรบุรุษในตำนานนี้", "thúk khon rúu-jàk wii-rá-bù-rùt nai tam-naan níi"),
  ("We must pass this ancient teaching on to the younger generation.", "เราต้องถ่ายทอดคำสอนโบราณนี้ให้คนรุ่นหลัง", "rao tɔ̂ng thàai-thɔ̂ɔt kham-sɔ̌ɔn boo-raan níi hâi khon rûn lǎng"),
 ],
 "b1u7x7": [
  ("This monument was built in the fifteenth century.", "โบราณสถานนี้สร้างในศตวรรษที่สิบห้า", "boo-raan-sà-thǎan níi sâang nai sàt-tà-wát thîi sìp-hâa"),
  ("Excavations are still going on at this archaeological site.", "แหล่งโบราณคดีนี้ยังมีการขุดค้นอยู่", "lɛ̀ng boo-raan-ná-khá-dii níi yang mii kaan khùt-khón yùu"),
  ("The most interesting finds are now kept in the museum.", "ของที่ขุดพบซึ่งน่าสนใจที่สุดตอนนี้เก็บไว้ในพิพิธภัณฑ์", "khɔ̌ɔng thîi khùt phóp sʉ̂ng nâa-sǒn-jai thîi-sùt tɔɔn-níi kèp wái nai phí-phít-thá-phan"),
  ("The museum's collection has more than ten thousand objects.", "พิพิธภัณฑ์มีของสะสมมากกว่าหนึ่งหมื่นชิ้น", "phí-phít-thá-phan mii khɔ̌ɔng-sà-sǒm mâak kwàa nʉ̀ng mʉ̀ʉn chín"),
  ("Nobody knows when the restoration work will be finished.", "ไม่มีใครรู้ว่างานบูรณะจะเสร็จเมื่อไร", "mâi mii khrai rúu wâa ngaan buu-rá-ná jà sèt mʉ̂a-rai"),
  ("Preserving cultural heritage is the duty of each of us.", "การอนุรักษ์มรดกทางวัฒนธรรมเป็นหน้าที่ของเราทุกคน", "kaan à-nú-rák mɔɔ-rá-dòk thaang wát-thá-ná-tham pen nâa-thîi khɔ̌ɔng rao thúk khon"),
  ("The Silk Road connected China with Europe.", "เส้นทางสายไหมเชื่อมจีนกับยุโรป", "sên-thaang-sǎai-mǎi chʉ̂am jiin kàp yú-ròop"),
  ("Merchants brought goods to Ayutthaya by ship.", "พ่อค้านำสินค้ามาที่อยุธยาทางเรือ", "phɔ̂ɔ-kháa nam sǐn-kháa maa thîi à-yút-thá-yaa thaang rʉa"),
  ("During the Ayutthaya period, many beautiful temples were built.", "ในสมัยอยุธยา มีการสร้างวัดที่สวยงามมากมาย", "nai sà-mǎi à-yút-thá-yaa, mii kaan sâang wát thîi sǔai-ngaam mâak-maai"),
  ("I've read many books about the Roman Empire.", "ฉันอ่านหนังสือเกี่ยวกับจักรวรรดิโรมันมาหลายเล่ม", "chǎn àan nǎng-sʉ̌ʉ kìao-kàp jàk-krà-wàt roo-man maa lǎai lêm"),
  ("Our ancestors lived in these lands thousands of years ago.", "บรรพบุรุษของเราอาศัยอยู่บนแผ่นดินนี้เมื่อหลายพันปีก่อน", "ban-phá-bù-rùt khɔ̌ɔng rao aa-sǎi yùu bon phɛ̀n-din níi mʉ̂a lǎai phan pii kɔ̀ɔn"),
  ("My grandfather, who saw the war, always says we must value peace.", "ปู่ที่เคยผ่านสงครามบอกเสมอว่าเราต้องเห็นคุณค่าของสันติภาพ", "pùu thîi khəəi phàan sǒng-khraam bɔ̀ɔk sà-mə̌ə wâa rao tɔ̂ng hěn khun-khâa khɔ̌ɔng sǎn-tì-phâap"),
 ],
 "b1u7x8": [
  ("I went to Italy through a cultural exchange program.", "ฉันไปอิตาลีผ่านโครงการแลกเปลี่ยนวัฒนธรรม", "chǎn pai ì-taa-lîi phàan khroong-kaan lɛ̂ɛk-plìan wát-thá-ná-tham"),
  ("Curiosity about others and respect for differences are the foundation of friendship.", "ความอยากรู้จักผู้อื่นและการเคารพความแตกต่างคือรากฐานของมิตรภาพ", "khwaam-yàak-rúu-jàk phûu-ʉ̀ʉn lɛ́ kaan khao-róp khwaam-tɛ̀ɛk-tàang khʉʉ râak-thǎan khɔ̌ɔng mít-trà-phâap"),
  ("We want our children to grow up bilingual.", "เราอยากให้ลูกโตมาพูดได้สองภาษา", "rao yàak hâi lûuk too maa phûut dâai sɔ̌ɔng phaa-sǎa"),
  ("From my accent, people immediately know I'm a foreigner.", "ฟังจากสำเนียง คนก็รู้ทันทีว่าฉันเป็นชาวต่างชาติ", "fang jàak sǎm-niang, khon kɔ̂ɔ rúu than-thii wâa chǎn pen chaao-tàang-châat"),
  ("When I came to Italy, I experienced culture shock in the first months.", "ตอนมาอิตาลี ช่วงเดือนแรกๆ ฉันเจอภาวะช็อกทางวัฒนธรรม", "tɔɔn maa ì-taa-lîi, chûang dʉan rɛ̂ɛk-rɛ̂ɛk chǎn jəə phaa-wá chɔ́k thaang wát-thá-ná-tham"),
  ("It takes time to understand the unwritten rules here.", "ต้องใช้เวลากว่าจะเข้าใจกฎที่ไม่ได้เขียนไว้ของที่นี่", "tɔ̂ng chái wee-laa kwàa jà khâo-jai kòt thîi mâi dâai khǐan wái khɔ̌ɔng thîi-nîi"),
  ("In Italy, the meaning of this gesture is completely different.", "ที่อิตาลี ท่าทางนี้มีความหมายต่างไปโดยสิ้นเชิง", "thîi ì-taa-lîi, thâa-thaang níi mii khwaam-mǎai tàang pai dooi sîn-chəəng"),
  ("At the office there's a lot of formality, but among friends there's closeness.", "ที่ออฟฟิศเป็นทางการมาก แต่ในหมู่เพื่อนจะสนิทสนมกัน", "thîi ɔ́ɔp-fít pen-thaang-kaan mâak, tɛ̀ɛ nai mùu phʉ̂an jà sà-nìt-sà-nǒm kan"),
  ("At a first meeting, salary is considered a taboo topic.", "ในการพบกันครั้งแรก เรื่องเงินเดือนถือเป็นเรื่องต้องห้าม", "nai kaan phóp kan khráng rɛ̂ɛk, rʉ̂ang ngən-dʉan thʉ̌ʉ pen rʉ̂ang tɔ̂ng-hâam"),
  ("It's just a cultural stereotype; not all Italians are like that.", "นั่นเป็นแค่ภาพเหมารวมทางวัฒนธรรม คนอิตาลีไม่ได้เป็นแบบนั้นทุกคน", "nân pen khɛ̂ɛ phâap-mǎo-ruam thaang wát-thá-ná-tham, khon ì-taa-lîi mâi dâai pen bɛ̀ɛp nán thúk khon"),
  ("I've adapted, and now I feel at home in this city.", "ฉันปรับตัวได้แล้ว ตอนนี้รู้สึกเหมือนอยู่บ้านในเมืองนี้", "chǎn pràp-tua dâai lɛ́ɛo, tɔɔn-níi rúu-sʉ̀k mʉ̌an yùu bâan nai mʉang níi"),
  ("Sometimes I don't know which culture I belong to.", "บางครั้งฉันก็ไม่รู้ว่าตัวเองเป็นคนของวัฒนธรรมไหน", "baang khráng chǎn kɔ̂ɔ mâi rúu wâa tua-eeng pen khon khɔ̌ɔng wát-thá-ná-tham nǎi"),
 ],
}
